 public static function text($v,int $min=0,int $max=1000): string {if(!is_scalar($v))throw new \InvalidArgumentException('متن معتبر نیست.');$v=trim(strip_tags((string)$v));if(mb_strlen($v)<$min||mb_strlen($v)>$max)throw new \InvalidArgumentException('طول متن معتبر نیست.');return $v;}
