 public static function dateUtc($v,bool $end=false): string {$s=self::text($v,10,25);try{$d=new \DateTimeImmutable($s,new \DateTimeZone('UTC'));}catch(\Throwable $e){throw new \InvalidArgumentException('تاریخ معتبر نیست.');}return $d->setTimezone(new \DateTimeZone('UTC'))->format('c');}
