 public static function defects(array $rows): array {$out=[];foreach($rows as $key=>$r){$code=self::code(is_string($key)?$key:(string)($r['code']??''));if(isset($out[$code]))throw new \InvalidArgumentException('کد عیب تکراری است.');$severity=(string)($r['severity']??'warning');if(!in_array($severity,['info','warning','critical'],true))throw new \InvalidArgumentException('شدت عیب معتبر نیست.');$out[$code]=['title'=>self::text($r['title']??'',3,120),'severity'=>$severity,'active'=>!empty($r['active'])];}if(count($out)>100)throw new \InvalidArgumentException('حداکثر ۱۰۰ کد عیب مجاز است.');return $out;}
 public static function orderSnapshot($order): array {$shipping=[];foreach($order->get_items('shipping') as $item)$shipping[]=(string)$item->get_method_id();$items=[];$virtual=true;foreach($order->get_items() as $id=>$item){$p=$item->get_product();if($p&&!$p->is_virtual())$virtual=false;$items[]=[(int)$id,(int)$item->get_product_id(),(float)$item->get_quantity()];}$created=$order->get_date_created();return ['order_id'=>(int)$order->get_id(),'version'=>(string)$order->get_version(),'status'=>(string)$order->get_status(),'created'=>$created?$created->getTimestamp():0,'shipping'=>array_values(array_unique($shipping)),'virtual'=>$virtual,'refunded'=>(float)$order->get_total()>0&&(float)$order->get_total_refunded()>=(float)$order->get_total(),'station'=>(string)$order->get_meta('_hm_mahex_station_id',true),'materials'=>(array)$order->get_meta('_hm_mahex_material_usage',true),'fingerprint'=>self::hash([$order->get_status(),$items,$shipping])];}
 public static function eligible(array $snap,array $settings): array {if($snap['virtual'])return [false,'virtual'];if(in_array($snap['status'],['cancelled','refunded','failed'],true)||$snap['refunded'])return [false,'inactive'];$from=strtotime($settings['from']);$to=strtotime($settings['to']);if($snap['created']<$from||$snap['created']>$to)return [false,'date'];if($settings['statuses']&&!in_array($snap['status'],$settings['statuses'],true))return [false,'status'];if($settings['methods']&&!array_intersect($settings['methods'],$snap['shipping']))return [false,'method'];return [true,''];}
 public static function population(array $settings): array {$ids=wc_get_orders(['limit'=>self::integer($settings['population_limit'],1,1000),'return'=>'ids','date_created'=>strtotime($settings['from']).'...'.strtotime($settings['to']),'orderby'=>'ID','order'=>'ASC']);$ok=[];$excluded=[];foreach($ids as $id){$o=wc_get_order($id);if(!$o||!self::canView((int)$id))continue;$s=self::orderSnapshot($o);[$yes,$why]=self::eligible($s,$settings);if($yes)$ok[(int)$id]=$s;else $excluded[(int)$id]=$why;}return [$ok,$excluded];}
 /** Deterministic local sampler; risk is a stored local score, never a carrier signal. */
 public static function select(array $population,string $mode,int $value,string $seed): array {if(!in_array($mode,self::SAMPLE_MODES,true))throw new \InvalidArgumentException('روش نمونه‌گیری معتبر نیست.');if(!$population)return [];$rows=array_values($population);usort($rows,static fn($a,$b)=>strcmp(self::hash([$seed,$a['order_id']]),self::hash([$seed,$b['order_id']])));$n=count($rows);if($mode==='fixed')$take=min($n,$value);elseif($mode==='percent')$take=min($n,max(1,(int)ceil($n*$value/100)));elseif($mode==='interval'){$out=[];foreach($rows as $i=>$r)if($i%$value===0)$out[]=$r;return $out;}else {usort($rows,static fn($a,$b)=>(int)($b['risk']??0)<=>(int)($a['risk']??0)?:$a['order_id']<=>$b['order_id']);$take=min($n,$value);}return array_slice($rows,0,$take);}
 public static function baseSettings(array $p): array {$statuses=array_values(array_unique(array_filter((array)($p['statuses']??[]),'is_string')));foreach($statuses as $s)if(!array_key_exists($s,wc_get_order_statuses())&&!array_key_exists('wc-'.$s,wc_get_order_statuses()))throw new \InvalidArgumentException('وضعیت سفارش ناشناخته است.');$methods=array_values(array_unique(array_map(static fn($v)=>self::text($v,1,80),(array)($p['methods']??[]))));$from=self::dateUtc($p['from']??'');$to=self::dateUtc($p['to']??'');if(strtotime($to)<strtotime($from))throw new \InvalidArgumentException('پایان بازه پیش از آغاز است.');$mode=(string)($p['mode']??'fixed');$value=self::integer($p['value']??1,1,$mode==='percent'?100:1000);return ['from'=>$from,'to'=>$to,'statuses'=>$statuses,'methods'=>$methods,'mode'=>$mode,'value'=>$value,'seed'=>self::text($p['seed']??'',3,80),'sample_cap'=>self::integer($p['sample_cap']??100,1,500),'population_limit'=>self::integer($p['population_limit']??500,1,1000),'overlap'=>in_array(($p['overlap']??''),['deny','warn'],true)?$p['overlap']:'warn','minimum_station_sample'=>self::integer($p['minimum_station_sample']??5,1,1000),'target_rate'=>min(100,max(0,(float)($p['target_rate']??5)))];}
 private static function event(array &$c,string $intent,array $detail=[]): void {if(count($c['history'])>=500)throw new \RuntimeException('ظرفیت تاریخچه کمپین پر شده است.');$c['history'][]=['intent'=>$intent,'detail'=>$detail,'actor'=>get_current_user_id(),'at'=>gmdate('c')];}
 private static function save(array $all,array $c): void {$all[$c['id']]=$c;if(!update_option(self::OPTION,$all,false))throw new \RuntimeException('ذخیره کمپین موفق نشد.');}
 public static function create(array $p,?array $suppliedPopulation=null): array {if(!self::canManage())throw new \RuntimeException('مدیریت کمپین مجاز نیست.');$all=self::catalog();if(count($all)>=100)throw new \RuntimeException('ظرفیت ۱۰۰ کمپین پر است.');$settings=self::baseSettings($p);[$population,$excluded]=$suppliedPopulation===null?self::population($settings):[$suppliedPopulation,[]];$chosen=self::select($population,$settings['mode'],$settings['value'],$settings['seed']);if(count($chosen)>$settings['sample_cap'])$chosen=array_slice($chosen,0,$settings['sample_cap']);$id=bin2hex(random_bytes(12));$members=[];foreach($chosen as $s){$oid=(int)$s['order_id'];if(self::activeMembership($oid,$all)&&$settings['overlap']==='deny')continue;$members[$oid]=['order_id'=>$oid,'snapshot'=>$s,'source'=>'sample','source_reason'=>'','lane'=>'pending','answers'=>[],'defects'=>[],'inspections'=>[],'disposition'=>'','quarantine'=>null,'revision'=>1,'updated_at'=>gmdate('c')];}$template=self::template($p['template']??self::DEFAULT_TEMPLATE);$c=['id'=>$id,'code'=>'MHQA-'.strtoupper(substr($id,0,12)),'name'=>self::text($p['name']??'',3,120),'purpose'=>self::text($p['purpose']??'',3,500),'state'=>'draft','revision'=>1,'created_at'=>gmdate('c'),'updated_at'=>gmdate('c'),'settings'=>$settings,'population_fingerprint'=>self::hash(array_map(static fn($s)=>[$s['order_id'],$s['fingerprint']],$population)),'population_count'=>count($population),'excluded'=>$excluded,'template_version'=>1,'template'=>$template,'defects'=>self::defects($p['defects']??self::DEFAULT_DEFECTS),'members'=>$members,'history'=>[]];self::event($c,'create',['members'=>count($members),'population'=>count($population)]);self::save($all,$c);return $c;}
 public static function get(string $id): array {$id=self::id($id);$c=self::catalog()[$id]??null;if(!$c)throw new \RuntimeException('کمپین وجود ندارد.');if(!self::canView())throw new \RuntimeException('دسترسی مجاز نیست.');foreach($c['members'] as $oid=>$m)if(!self::canView((int)$oid))throw new \RuntimeException('دسترسی یکی از سفارش‌ها مجاز نیست.');$c['summary']=self::summary($c);$c['drift']=self::drift($c);return $c;}
 public static function activeMembership(int $orderId,?array $all=null,string $except=''): bool {foreach($all??self::catalog() as $id=>$c)if($id!==$except&&!in_array($c['state'],['closed','cancelled'],true)&&isset($c['members'][$orderId]))return true;return false;}
 public static function drift(array $c): array {$out=[];foreach($c['members'] as $oid=>$m){$o=wc_get_order((int)$oid);if(!$o){$out[$oid]='missing';continue;}$now=self::orderSnapshot($o);if(!hash_equals($m['snapshot']['fingerprint'],$now['fingerprint'])||$m['snapshot']['status']!==$now['status'])$out[$oid]='changed';}return $out;}
 public static function mutate(string $id,int $revision,string $intent,array $p=[]): array {$all=self::catalog();$c=$all[self::id($id)]??null;if(!$c)throw new \RuntimeException('کمپین وجود ندارد.');if($c['revision']!==$revision)throw new \RuntimeException('نسخه کمپین تغییر کرده است.');if(in_array($c['state'],['closed','cancelled'],true))throw new \RuntimeException('کمپین نهایی فقط خواندنی است.');if(in_array($intent,['add','remove','regenerate','activate','cancel','close','defects'],true)&&!self::canManage())throw new \RuntimeException('مدیریت کمپین مجاز نیست.');$detail=[];
