  elseif($intent==='cancel'){$reason=self::text($p['reason']??'',3,500);$c['state']='cancelled';$detail=['reason'=>$reason];}
  elseif($intent==='close'){if(!in_array($c['state'],['active','review'],true))throw new \RuntimeException('کمپین فعال یا بازبینی لازم است.');foreach($c['members'] as $m)if($m['lane']!=='released')throw new \RuntimeException('همه اعضا باید تعیین تکلیف شوند.');$c['state']='closed';$detail=['summary'=>self::summary($c)];}
  elseif($intent==='add'||$intent==='remove'){if($c['state']!=='draft')throw new \RuntimeException('عضویت پس از قفل تغییر نمی‌کند.');$oid=self::integer($p['order_id']??0,1,PHP_INT_MAX);$reason=self::text($p['reason']??'',3,500);if($intent==='remove'){if(!isset($c['members'][$oid]))throw new \RuntimeException('سفارش عضو نیست.');unset($c['members'][$oid]);}else {$o=wc_get_order($oid);if(!$o||!self::canView($oid))throw new \RuntimeException('سفارش موجود یا قابل دسترسی نیست.');if(isset($c['members'][$oid]))throw new \RuntimeException('سفارش عضو است.');if(self::activeMembership($oid,$all,$id)&&$c['settings']['overlap']==='deny')throw new \RuntimeException('هم‌پوشانی کمپین ممنوع است.');$s=self::orderSnapshot($o);$c['members'][$oid]=['order_id'=>$oid,'snapshot'=>$s,'source'=>'manual','source_reason'=>$reason,'lane'=>'pending','answers'=>[],'defects'=>[],'inspections'=>[],'disposition'=>'','quarantine'=>null,'revision'=>1,'updated_at'=>gmdate('c')];}$detail=['order_id'=>$oid,'reason'=>$reason];}
