  else throw new \InvalidArgumentException('عملیات کمپین معتبر نیست.');
  $c['revision']++;$c['updated_at']=gmdate('c');self::event($c,$intent,$detail);self::save($all,$c);return $c;}
 public static function inspect(string $id,int $campaignRevision,int $orderId,int $memberRevision,array $answers,array $defects,string $disposition,string $observation,bool $human,bool $blind=false): array {$all=self::catalog();$c=$all[self::id($id)]??null;if(!$c||$c['revision']!==$campaignRevision)throw new \RuntimeException('نسخه کمپین تغییر کرده است.');if($c['state']!=='active')throw new \RuntimeException('کمپین فعال نیست.');if(!self::canInspect($orderId)||!isset($c['members'][$orderId]))throw new \RuntimeException('بازرسی مجاز نیست.');$m=$c['members'][$orderId];if($m['revision']!==$memberRevision)throw new \RuntimeException('نسخه عضو تغییر کرده است.');if(!$human)throw new \InvalidArgumentException('تأیید مشاهده فیزیکی دستی لازم است.');$observation=self::text($observation,3,1000);$normalized=[];$critical=false;foreach($c['template'] as $criterion){$a=$answers[$criterion['code']]??null;if(!in_array($a,self::ANSWERS,true))throw new \InvalidArgumentException('پاسخ همه معیارها لازم است.');$note=self::text($answers[$criterion['code'].'_note']??'',0,500);if(($a==='fail'||$a==='not_applicable')&&$note==='')throw new \InvalidArgumentException('شکست و نامرتبط نیازمند توضیح است.');if($a==='fail'&&$criterion['severity']==='critical')$critical=true;$normalized[$criterion['code']]=['answer'=>$a,'note'=>$note,'severity'=>$criterion['severity'],'weight'=>$criterion['weight']];}$defectRows=[];foreach(array_unique($defects) as $code){$code=self::code($code);if(empty($c['defects'][$code]['active']))throw new \InvalidArgumentException('کد عیب فعال نیست.');$defectRows[$code]=$c['defects'][$code];if($c['defects'][$code]['severity']==='critical')$critical=true;}if(!in_array($disposition,self::DISPOSITIONS,true))throw new \InvalidArgumentException('تصمیم معتبر نیست.');if($critical&&$disposition==='pass')throw new \RuntimeException('شکست بحرانی قابل پذیرش مستقیم نیست.');$record=['id'=>bin2hex(random_bytes(8)),'actor'=>get_current_user_id(),'at'=>gmdate('c'),'human_observation'=>true,'ob