 public static function move(string $id,int $campaignRevision,int $orderId,int $memberRevision,string $lane,string $reason=''): array {$all=self::catalog();$c=$all[self::id($id)]??null;if(!$c||$c['revision']!==$campaignRevision)throw new \RuntimeException('نسخه کمپین تغییر کرده است.');if(!isset($c['members'][$orderId])||!self::canInspect($orderId))throw new \RuntimeException('جابه‌جایی مجاز نیست.');if(!in_array($lane,self::LANES,true))throw new \InvalidArgumentException('ستون معتبر نیست.');$m=$c['members'][$orderId];if($m['revision']!==$memberRevision)throw new \RuntimeException('نسخه کارت تغییر کرده است.');$allowed=['pending'=>['inspecting'],'inspecting'=>['pending','rework','review','released'],'rework'=>['inspecting','review'],'review'=>['rework','released'],'released'=>['review']];if(!in_array($lane,$allowed[$m['lane']]??[],true))throw new \RuntimeException('گذار برد مجاز نیست.');if($lane==='released'&&self::memberQuarantined($m))throw new \RuntimeException('عضو قرنطینه‌شده آزاد نمی‌شود.');if(in_array($lane,['review','released'],true)&&!$m['inspections'])throw new \RuntimeException('بازرسی ثبت‌شده لازم است.');if($reason!=='')$reason=self::text($reason,3,500);$from=$m['lane'];$m['lane']=$lane;$m['revision']++;$m['updated_at']=gmdate('c');$c['members'][$orderId]=$m;$c['revision']++;self::event($c,'move',['order_id'=>$orderId,'from'=>$from,'to'=>$lane,'reason'=>$reason]);self::save($all,$c);return $c;}
 public static function secondReview(string $id,int $revision,int $orderId,bool $release,string $reason): array {$all=self::catalog();$c=$all[self::id($id)]??null;if(!$c||$c['revision']!==$revision)throw new \RuntimeException('نسخه کمپین تغییر کرده است.');if(!self::canManage()||!isset($c['members'][$orderId]))throw new \RuntimeException('بازبینی دوم مجاز نیست.');$m=$c['members'][$orderId];$last=end($m['inspections']);if(!$last||$last['actor']===get_current_user_id())throw new \RuntimeException('بازبین دوم باید کاربر متفاوت باشد.');$reason=self::text($reason,3,500);$review=['actor'=>get_current_user_id(),'at'=>gmdate('c'),'release'=>$release,'reason'=>$reason];$m['inspections'][count($m['inspections'])-1]['second_review']=$review;if($release&&self::memberQuarantined($m)){$m['quarantine']['open']=false;$m['quarantine']['released_by']=$review['actor'];$m['quarantine']['released_at']=$review['at'];$m['quarantine']['release_reason']=$reason;$m['lane']='released';}$m['revision']++;$c['members'][$orderId]=$m;$c['revision']++;self::event($c,'second_review',['order_id'=>$orderId,'release'=>$release,'reason'=>$reason]);self::save($all,$c);return $c;}
 public static function memberQuarantined(array $m): bool {return !empty($m['quarantine']['open']);}
 public static function hasOpenQuarantine(int $orderId): bool {foreach(self::catalog() as $c)if(!in_array($c['state'],['cancelled'],true)&&isset($c['members'][$orderId])&&self::memberQuarantined($c['members'][$orderId]))return true;return false;}
 public static function assertNoQuarantine(int $orderId): void {if(self::hasOpenQuarantine($orderId))throw new \RuntimeException('این سفارش در تضمین کیفیت بسته‌بندی قرنطینه است.');}
 public static function summary(array $c): array {$s=['members'=>count($c['members']),'lanes'=>array_fill_keys(self::LANES,0),'inspected'=>0,'failed'=>0,'quarantined'=>0,'defects'=>[],'score_total'=>0,'score_denominator'=>0];foreach($c['members'] as $m){$s['lanes'][$m['lane']]++;if($m['inspections'])$s['inspected']++;if(self::memberQuarantined($m))$s['quarantined']++;foreach($m['answers'] as $a)if($a['answer']!=='not_applicable'){$s['score_denominator']+=$a['weight'];if($a['answer']==='fail'){$s['failed']++;$s['score_total']+=$a['weight'];}}foreach($m['defects'] as $code=>$d)$s['defects'][$code]=($s['defects'][$code]??0)+1;}arsort($s['defects']);$s['defect_rate']=$s['score_denominator']?round(100*$s['score_total']/$s['score_denominator'],2):0;$total=max(1,array_sum($s['defects']));$cum=0;$s['pareto']=[];foreach($s['defects'] as $code=>$count){$cum+=$count;$s['pareto'][]=['code'=>$code,'count'=>$count,'cumulative_percent'=>round(100*$cum/$total,2)];}$s['threshold_exceeded']=$s['defect_rate']>(float)$c['settings']['target_rate'];return $s;}
 public static function analytics(array $campaigns): array {$weeks=[];$stations=[];$materials=[];foreach($campaigns as $c){if($c['state']!=='closed')continue;foreach($c['members'] as $m){foreach($m['inspections'] as $inspection){$week=gmdate('o-\WW',strtotime($inspection['at']));$key=$week.':v'.$inspection['template_version'];$weeks[$key]['inspections']=($weeks[$key]['inspections']??0)+1;$fails=count(array_filter($inspection['answers'],static fn($a)=>$a['answer']==='fail'));$weeks[$key]['failures']=($weeks[$key]['failures']??0)+$fails;}$station=$m['snapshot']['station']?:'unassigned';$stations[$station]['sample']=($stations[$station]['sample']??0)+($m['inspections']?1:0);$stations[$station]['defects']=($stations[$station]['defects']??0)+count($m['defects']);foreach($m['snapshot']['materials'] as $material=>$qty)$materials[$material]['observations'][]=['quantity'=>$qty,'defects'=>count($m['defects'])];}}return ['weeks'=>$weeks,'stations'=>$stations,'materials'=>$materials,'causality_claimed'=>false];}
 public static function csv(array $c): string {$fp=fopen('php://temp','r+');fputcsv($fp,['campaign','order_id','lane','disposition','inspection_count','defect_codes','human_observation']);foreach($c['members'] as $m)fputcsv($fp,[$c['code'],$m['order_id'],$m['lane'],$m['disposition'],count($m['inspections']),implode('|',array_keys($m['defects'])),$m['inspections']?'yes':'no']);rewind($fp);$out=stream_get_contents($fp);fclose($fp);return $out;}
 public static function privacyForUser(int $userId): array {$out=[];foreach(self::catalog() as $c){$events=array_values(array_filter($c['history'],static fn($e)=>(int)$e['actor']===$userId));$inspections=[];foreach($c['members'] as $m)foreach($m['inspections'] as $i)if((int)$i['actor']===$userId||((int)($i['second_review']['actor']??0)===$userId))$inspections[]=['order_id'=>$m['order_id'],'inspection'=>$i];if($events||$inspections)$out[]=['campaign'=>$c['id'],'events'=>$events,'inspections'=>$inspections];}return $out;}
 public static function eraseUser(int $userId): int {$all=self::catalog();$changed=0;foreach($all as &$c){foreach($c['history'] as &$e)if((int)$e['actor']===$userId){$e['actor']=0;$changed++;}unset($e);foreach($c['members'] as &$m){if((int)($m['quarantine']['actor']??0)===$userId){$m['quarantine']['actor']=0;$changed++;}if((int)($m['quarantine']['released_by']??0)===$userId){$m['quarantine']['released_by']=0;$changed++;}foreach($m['inspections'] as &$i){if((int)$i['actor']===$userId){$i['actor']=0;$changed++;}if((int)($i['second_review']['actor']??0)===$userId){$i['second_review']['actor']=0;$changed++;}}unset($i);}unset($m);}unset($c);if($changed&&!update_option(self::OPTION,$all,false))throw new \RuntimeException('ناشناس‌سازی داده کاربر موفق نشد.');return $changed;}
 public static function ajax(): void {if(!check_ajax_referer(self::NONCE,'nonce',false)||!self::canView())wp_send_json_error(['message'=>'دسترسی مجاز نیست.'],403);try{$raw=$_POST['payload']??'';if(!is_string($raw)||strlen($raw)>50000)throw new \InvalidArgumentException('درخواست بیش از حد مجاز است.');$p=json_decode(wp_unslash($raw),true);if(!is_array($p))throw new \InvalidArgumentException('درخواست نامعتبر است.');$intent=(string)($p['intent']??'');if($intent==='inspect')$r=self::inspect((string)$p['id'],(int)$p['revision'],(int)$p['order_id'],(int)$p['member_revision'],(array)$p['answers'],(array)$p['defects'],(string)$p['disposition'],(string)$p['observation'],!empty($p['human']),!empty($p['blind']));elseif($intent==='move')$r=self::move((string)$p['id'],(int)$p['revision'],(int)$p['order_id'],(int)$p['member_revision'],(string)$p['lane'],(string)($p['reason']??''));elseif($intent==='second_review')$r=self::secondReview((string)$p['id'],(int)$p['revision'],(int)$p['order_id'],!empty($p['release']),(string)$p['reason']);else $r=self::mutate((string)$p['id'],(int)$p['revision'],$intent,(array)($p['data']??[]));wp_send_json_success(['revision'=>$r['revision'],'reload'=>true]);}catch(\Throwable $e){wp_send_json_error(['message'=>$e->getMessage()],409);}}
 public static function download(): void {check_admin_referer(self::NONCE);$c=self::get((string)($_GET['campaign']??''));nocache_headers();header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="mahex-qa-'.$c['code'].'.csv"');echo "\xEF\xBB\xBF".self::csv($c);exit;}
 public static function printSheet(): void {check_admin_referer(self::NONCE);$c=self::get((string)($_GET['campaign']??''));echo '<!doctype html><html dir="rtl" lang="fa"><meta charset="utf-8"><title>'.esc_html($c['code']).'</title><style>body{font-family:Tahoma;margin:2cm}article{break-inside:avoid;border:1px solid #777;padding:12px;margin:12px}li{line-height:2}</style><h1>برگه بازرسی دستی '.esc_html($c['code']).'</h1><p><strong>این برگه تا ورود دستی در سامانه ثبت‌شده محسوب نمی‌شود.</strong></p>';foreach($c['members'] as $m){echo '<article><h2>سفارش #'.(int)$m['order_id'].'</h2><ol>';foreach($c['template'] as $criterion)echo '<li>'.esc_html($criterion['title']).' □ قبول □ رد □ نامرتبط</li>';echo '</ol><p>یادداشت: ....................................................................</p><p>نام و امضا: ........................ تاریخ: ................</p></article>';}echo '<script>window.print()</script>';exit;}
 public static function page(): void {if(!self::canView())wp_die('دسترسی مجاز نیست.','',['response'=>403]);$id=(string)($_GET['campaign']??'');echo '<div class="wrap hm-v36-sampling" dir="rtl"><h1>کمپین نمونه‌برداری کیفیت بسته‌بندی</h1><p class="notice notice-info">نتایج فقط مشاهده فیزیکی دستی کاربران مجاز است؛ هیچ دستگاه، API ماهکس، webhook یا تأیید شرکت حمل وجود ندارد.</p>';if(!$id){echo '<div class="hqs-list">';foreach(array_reverse(self::catalog()) as $c)echo '<a class="hqs-campaign" href="'.esc_url(add_query_arg(['page'=>self::SLUG,'campaign'=>$c['id']],admin_url('admin.php'))).'"><b>'.esc_html($c['name']).'</b><span>'.esc_html($c['code']).' · '.esc_html($c['state']).' · '.count($c['members']).' سفارش</span></a>';echo '</div></div>';return;}$c=self::get($id);$s=$c['summary'];echo '<header class="hqs-head"><div><h2>'.esc_html($c['name']).'</h2><p>'.esc_html($c['purpose']).'</p></div><div><b>'.esc_html($c['code']).'</b><br>نسخه '.(int)$c['revision'].' · '.esc_html($c['state']).'</div></header><nav><a class="button" href="'.esc_url(wp_nonce_url(add_query_arg(['action'=>'hm_mahex_v36_sampling_export','campaign'=>$c['id']],admin_url('admin-post.php')),self::NONCE)).'">CSV کم‌داده</a> <a class="button" target="_blank" href="'.esc_url(wp_nonce_url(add_query_arg(['action'=>'hm_mahex_v36_sampling_print','campaign'=>$c['id']],admin_url('admin-post.php')),self::NONCE)).'">برگه چاپ آفلاین</a></nav><section class="hqs-metrics"><b>'.$s['inspected'].' بازرسی‌شده</b><b>'.$s['quarantined'].' قرنطینه باز</b><b>'.$s['defect_rate'].'٪ نرخ وزنی</b><b>'.($s['threshold_exceeded']?'عبور از هدف داخلی':'در محدوده هدف').'</b></section><div class="hqs-filter"><label>جست‌وجوی شناسه سفارش <input type="search" data-hqs-search></label><label>ستون <select data-hqs-lane><option value="">همه</option>';foreach(self::LANES as $lane)echo '<option value="'.$lane.'">'.$lane.'</option>';echo '</select></label></div><p data-hqs-live aria-live="polite"></p><div class="hqs-board" data-campaign="'.esc_attr($c['id']).'" data-revision="'.$c['revision'].'">';foreach(self::LANES as $lane){echo '<section class="hqs-lane" data-lane="'.$lane.'"><h3>'.$lane.' <span>'.$s['lanes'][$lane].'</span></h3><div class="hqs-drop" data-drop="'.$lane.'">';foreach($c['members'] as $m)if($m['lane']===$lane){echo '<article class="hqs-card" draggable="true" tabindex="0" data-order="'.$m['order_id'].'" data-member-revision="'.$m['revision'].'" data-lane="'.$lane.'"><b>سفارش #'.$m['order_id'].'</b><small>'.esc_html($m['disposition']?:'بدون تصمیم').'</small>';if(self::memberQuarantined($m))echo '<strong class="hqs-quarantine">قرنطینه باز</strong>';echo '<label>انتقال با صفحه‌کلید <select data-hqs-move><option value="">انتخاب ستون</option>';foreach(self::LANES as $to)echo '<option value="'.$to.'">'.$to.'</option>';echo '</select></label></article>';}echo '</div></section>';}echo '</div></div>';}
}
